import Path from "../path.js";
export function getInclude(fromDir, to, fs) {
    // Absolute path
    if (to.startsWith("/_includes/")) {
        return fs.entries.get(to);
    }
    // Relative path
    if (to.startsWith(".")) {
        return fs.entries.get(Path.join("/", fromDir, to));
    }
    // Get from _includes folder
    return fs.entries.get(Path.join("/_includes", to));
}
